import { conform, validate } from './contracts.mjs';

export class StructuredOutputError extends Error {
  constructor(kind) { super(kind); this.kind = kind; }
}

// Accept one complete object, including an otherwise unchanged object surrounded
// by explanatory text or a Markdown fence. Never repair values or choose between
// multiple objects; malformed/ambiguous output must be regenerated by the model.
export function parseStructuredContent(content, schema) {
  const text = content.trim().replace(/^\uFEFF/, '');
  let result;
  try { result = JSON.parse(text); }
  catch {
    const candidates = [];
    let start = -1, depth = 0, quoted = false, escaped = false;
    for (let i = 0; i < text.length; i++) {
      const char = text[i];
      if (start < 0) {
        if (char === '{' || char === '[') { start = i; depth = 1; quoted = false; escaped = false; }
        continue;
      }
      if (quoted) {
        if (escaped) escaped = false;
        else if (char === '\\') escaped = true;
        else if (char === '"') quoted = false;
      } else if (char === '"') quoted = true;
      else if (char === '{' || char === '[') depth++;
      else if (char === '}' || char === ']') {
        depth--;
        if (depth === 0) { candidates.push(text.slice(start, i + 1)); start = -1; }
      }
    }
    if (start >= 0 || candidates.length !== 1) throw new StructuredOutputError('format');
    try { result = JSON.parse(candidates[0]); }
    catch { throw new StructuredOutputError('format'); }
  }
  // Only keys the schema declares survive; a provider's own envelope fields or
  // an explicit null for an unused optional block are dropped rather than
  // failing an answer that is otherwise complete.
  const shaped = conform(result, schema);
  try { validate(shaped, schema); }
  catch { throw new StructuredOutputError('schema'); }
  return shaped;
}
